    let d: String
    var viewBox: CGFloat = 14

    static let left = IconShape(d: "M4.12587 2.19922C4.662 2.19922 5.09324 2.29246 5.41958 2.47894C5.76923 2.64211 6.06061 2.84024 6.29371 3.07334C6.52681 3.28313 6.72494 3.48127 6.88811 3.66775C7.05128 3.83092 7.23776 3.91251 7.44755 3.91251C7.65734 3.91251 7.85548 3.83092 8.04196 3.66775C8.25175 3.48127 8.4965 3.29479 8.77623 3.10831C9.05595 2.89852 9.38229 2.71204 9.75525 2.54887C10.1515 2.36239 10.6294 2.26915 11.1888 2.26915C11.8648 2.26915 12.4126 2.5139 12.8322 3.00341C13.2751 3.46961 13.4965 4.07567 13.4965 4.82159C13.4965 5.26449 13.4033 5.90551 13.2168 6.74467C13.0303 7.56052 12.7622 8.36472 12.4126 9.15726C12.0629 9.97311 11.6317 10.6724 11.1189 11.2552C10.6294 11.8612 10.0816 12.1643 9.47552 12.1643C8.84615 12.1643 8.35664 12.0594 8.00699 11.8496C7.68065 11.6631 7.41259 11.4416 7.2028 11.1852C6.99301 10.9521 6.80653 10.7307 6.64336 10.5209C6.5035 10.3111 6.31702 10.2062 6.08392 10.2062C5.85082 10.2062 5.61772 10.3111 5.38462 10.5209C5.17483 10.7307 4.93007 10.9521 4.65035 11.1852C4.37063 11.4416 4.05594 11.6747 3.70629 11.8845C3.35664 12.0943 2.93706 12.1992 2.44755 12.1992C1.6317 12.1992 1.01399 11.9195 0.594406 11.3601C0.198135 10.8006 0 10.1363 0 9.36705C0 8.99409 0.0699301 8.39968 0.20979 7.58383C0.37296 6.79129 0.617716 5.99875 0.944056 5.20621C1.2704 4.41367 1.68998 3.71437 2.2028 3.10831C2.73893 2.50225 3.37995 2.19922 4.12587 2.19922Z")
    static let right = IconShape(d: "M7.01524 1C7.34577 1 7.64325 1.09916 7.90767 1.29748C8.1721 1.4958 8.40347 1.72717 8.60179 1.9916C8.82215 2.25602 8.99843 2.52045 9.13064 2.78487C9.28489 3.02726 9.4171 3.20355 9.52728 3.31372C9.68153 3.46797 9.94596 3.60019 10.3206 3.71036C10.7172 3.82054 11.1138 3.96377 11.5105 4.14006C11.9291 4.29431 12.2927 4.50364 12.6012 4.76807C12.9097 5.03249 13.064 5.37404 13.064 5.79272C13.064 6.10121 12.9758 6.37666 12.7996 6.61905C12.6453 6.8394 12.458 7.07078 12.2376 7.31316C12.0393 7.55556 11.852 7.80896 11.6757 8.07339C11.5215 8.33782 11.4444 8.65733 11.4444 9.03193V10.7176C11.4444 10.916 11.4113 11.1363 11.3452 11.3787C11.3011 11.6211 11.213 11.8525 11.0808 12.0728C10.9486 12.2711 10.7833 12.4474 10.585 12.6017C10.4087 12.7339 10.1883 12.8 9.92392 12.8C9.54932 12.8 9.20777 12.7559 8.89927 12.6678C8.59077 12.5796 8.31533 12.4805 8.07294 12.3703C7.83055 12.2601 7.59918 12.161 7.37882 12.0728C7.1805 11.9847 6.9932 11.9406 6.81692 11.9406C6.6186 11.9406 6.4313 11.9847 6.25501 12.0728C6.10076 12.161 5.92448 12.2601 5.72616 12.3703C5.52784 12.4585 5.28545 12.5466 4.99899 12.6347C4.73456 12.7008 4.40403 12.7339 4.00739 12.7339C3.63279 12.7339 3.28022 12.5356 2.94969 12.1389C2.64119 11.7203 2.48695 11.2796 2.48695 10.8168V9.03193C2.48695 8.83361 2.3988 8.62428 2.22252 8.40392C2.06827 8.16153 1.89199 7.91914 1.69367 7.67675C1.49535 7.41233 1.30805 7.13688 1.13176 6.85042C0.977515 6.54192 0.900391 6.22241 0.900391 5.89188C0.900391 5.45117 1.04362 5.0986 1.33008 4.83417C1.61654 4.56975 1.94708 4.36041 2.32168 4.20616C2.69628 4.02988 3.05987 3.88665 3.41244 3.77647C3.765 3.66629 4.01841 3.53408 4.17266 3.37983C4.28284 3.26966 4.43709 3.08235 4.6354 2.81793C4.85576 2.5535 5.09815 2.28908 5.36258 2.02465C5.627 1.76022 5.90245 1.52885 6.18891 1.33053C6.47537 1.11018 6.75081 1 7.01524 1Z")

    func path(in rect: CGRect) -> Path {
        let scale = min(rect.width, rect.height) / viewBox
        func pt(_ x: CGFloat, _ y: CGFloat) -> CGPoint { CGPoint(x: rect.minX + x * scale, y: rect.minY + y * scale) }
        let tokens = d.replacingOccurrences(of: ",", with: " ")
            .replacingOccurrences(of: "([MLHVCZ])", with: " $1 ", options: .regularExpression)
            .split(separator: " ")
        var p = Path()
        var i = 0
        var command = ""
        var cur = CGPoint.zero  // 원본 좌표계의 현재 점
        func num() -> CGFloat { defer { i += 1 }; return CGFloat(Double(tokens[i]) ?? 0) }
        while i < tokens.count {
            if let c = tokens[i].first, c.isLetter {
                command = String(c)
                i += 1
                if command == "Z" { p.closeSubpath() }
                continue
            }
            switch command {
            case "M": cur = CGPoint(x: num(), y: num()); p.move(to: pt(cur.x, cur.y)); command = "L"
            case "L": cur = CGPoint(x: num(), y: num()); p.addLine(to: pt(cur.x, cur.y))
            case "H": cur.x = num(); p.addLine(to: pt(cur.x, cur.y))
            case "V": cur.y = num(); p.addLine(to: pt(cur.x, cur.y))
            case "C":
                let x1 = num(), y1 = num(), x2 = num(), y2 = num()
                cur = CGPoint(x: num(), y: num())
                p.addCurve(to: pt(cur.x, cur.y), control1: pt(x1, y1), control2: pt(x2, y2))
            default: i += 1
            }
        }
        return p
    }
}
